import java.util.*;class Main{public static void main(String[] args){String text="{[()]}";Deque<Character> stack=new ArrayDeque<>();boolean valid=true;for(char ch:text.toCharArray()){if("({[".indexOf(ch)>=0)stack.push(ch);else{if(stack.isEmpty()){valid=false;break;}char open=stack.pop();if((open=='('&&ch!=')')||(open=='{'&&ch!='}')||(open=='['&&ch!=']')){valid=false;break;}}}System.out.println(valid&&stack.isEmpty());}}
